var scene=UnityEditor.SceneManagement.EditorSceneManager.GetActiveScene();
var menu=UnityEditor.SceneManagement.EditorSceneManager.OpenScene("Assets/Scenes/MainMenu.unity",UnityEditor.SceneManagement.OpenSceneMode.Additive);
try{var manager=menu.GetRootGameObjects().SelectMany(x=>x.GetComponentsInChildren<MainMenuManager>(true)).First();var so=new SerializedObject(manager);var a=so.FindProperty("chapters");var chapters=new System.Collections.Generic.List<object>();for(int i=0;i<a.arraySize;i++){var c=(ChapterData)a.GetArrayElementAtIndex(i).objectReferenceValue;chapters.Add(new{number=c.chapterNumber,name=c.chapterName,waves=c.waves.Count,enemies=c.TotalEnemies,gold=c.startingGold});}return new {playing=EditorApplication.isPlaying,current=scene.path,dirty=scene.isDirty,chapters=chapters};}finally{UnityEditor.SceneManagement.EditorSceneManager.CloseScene(menu,true);}
